prompt:
请只写一个文件 mc_gate_h4.cpp（C++20，全局 main）。

【硬性约束】
1. 允许 include： "mc_gate_seed.h" "mc_gate_dgp.h" "mc_gate_adapter.h" "mc_gate_baselines.h"
   标准头：<cstdint> <cstddef> <cstdio> <string> <vector> <span> <cmath> <algorithm>
2. 不要重新定义任何已存在的函数。main 第一行 `using namespace mc_gate;`。
3. 构建带 -Werror，零警告。只打印规定的行。

【已有接口（逐字）】
  std::uint64_t seed_of(const std::string& key, int rep, int batch, const char* stream, std::uint64_t run_seed);
  ReturnMatrix generate_with_kappa(Family, Composition, int T, int N, double rho, double S,
                                   std::uint64_t seed, int kappa);
  WindowStats make_window_stats(const ResearchWindow&, bool abstain=false);
  struct WindowStats { std::vector<double> sr; double m; int T; int N; bool abstain; };
  Decision decide_from_stats(const WindowStats&, const RuleConfig&);
  struct RuleConfig { GateMode mode; double q; double alpha; };   // GateMode::Full
  double gate_teff(double T, double m);
  double gate_threshold_sr(double teff, double T, double N, double q);

【任务：H4 门槛回收】
参数：T=100, N=126, rho=0.30, S=1.2, Family::T5, Composition::OneGood,
      run_seed=20261027ULL, REPS=2000, Q=0.05
key 用 dataset_key("one_good", 1.2, 126, 100, 0.30, "t5", 50.4, 0)，kappa 固定 0。

对 rep = 0..1999：
    std::uint64_t s = seed_of(key, rep, 0, "ret", run_seed);
    ReturnMatrix m = generate_with_kappa(Family::T5, Composition::OneGood, T, N, 0.30, 1.2, s, 0);
    // m.r 已经是 trial-major 连续数组，直接取 span（不要写展平循环、没有 m.flat()）
    std::span<const double> sp(m.r.data(), m.r.size());
    ResearchWindow w{ sp, (std::size_t)T, (std::size_t)N, 0 };
    WindowStats st = make_window_stats(w, false);
    // 该 rep 的解析门槛
    double te = gate_teff((double)T, st.m);
    double thr = gate_threshold_sr(te, (double)T, (double)N, Q);
    // 该 rep 的最大 SR
    double mx = *std::max_element(st.sr.begin(), st.sr.end());
    bool sel = decide_from_stats(st, RuleConfig{ GateMode::Full, Q, Q }).selected;
    累计：thr_sum += thr; te_sum += te;
    若 sel：++nsel; 若 mx < lo_sel 则 lo_sel = mx;   （lo_sel 初值 +1e18）
    否则：  若 mx > hi_nosel 则 hi_nosel = mx;       （hi_nosel 初值 -1e18）

最后按顺序打印 4 行（全部 %.6f 或整数）：
  H4 lo_sel=<lo_sel> hi_nosel=<hi_nosel> nsel=<nsel> reps=2000
  THR mean=<thr_sum/2000> teff_mean=<te_sum/2000>
  GAP lo_gap=<lo_sel - thr_mean> hi_gap=<hi_nosel - thr_mean>
  H4_DONE

【输出纪律】共 4 行，格式如上，全部 printf 到 stdout。
